create extension if not exists "pgcrypto";
create table profiles (id uuid primary key references auth.users(id), full_name text, whatsapp text, city text, neighborhood text, preferred_exchange_method text, is_verified boolean default false, is_premium boolean default false, role text default 'user', reputation_score numeric default 0, completed_exchanges_count int default 0, reports_count int default 0, created_at timestamptz default now(), updated_at timestamptz default now());
create table albums (id uuid primary key default gen_random_uuid(), name text not null, slug text unique not null, total_stickers int not null, is_active boolean default true, created_at timestamptz default now());
create table stickers (id uuid primary key default gen_random_uuid(), album_id uuid references albums(id) on delete cascade, code text not null, number int not null, section text, created_at timestamptz default now(), unique(album_id, number));
create table user_stickers (id uuid primary key default gen_random_uuid(), user_id uuid references auth.users(id) on delete cascade, album_id uuid references albums(id), sticker_id uuid references stickers(id), status text check (status in ('needed','owned','duplicate')), quantity int default 1, created_at timestamptz default now(), updated_at timestamptz default now(), unique(user_id,sticker_id,status));
create table exchange_proposals (id uuid primary key default gen_random_uuid(), proposer_id uuid references auth.users(id), receiver_id uuid references auth.users(id), album_id uuid references albums(id), status text check (status in ('proposed','accepted','rejected','cancelled','completed','reported')) default 'proposed', exchange_method text check (exchange_method in ('in_person','shipping')), platform_fee_cop int default 0, is_protected boolean default false, created_at timestamptz default now(), updated_at timestamptz default now());
create table exchange_items (id uuid primary key default gen_random_uuid(), exchange_id uuid references exchange_proposals(id) on delete cascade, from_user_id uuid references auth.users(id), to_user_id uuid references auth.users(id), sticker_id uuid references stickers(id), quantity int default 1);
create table shipments (id uuid primary key default gen_random_uuid(), exchange_id uuid references exchange_proposals(id), provider text default 'servientrega', status text default 'pending', origin_city text, origin_address text, destination_city text, destination_address text, tracking_number text, shipping_cost_cop int, declared_value_cop int, created_at timestamptz default now(), updated_at timestamptz default now());
create table payments (id uuid primary key default gen_random_uuid(), user_id uuid references auth.users(id), exchange_id uuid references exchange_proposals(id), amount_cop int not null, concept text, provider text, status text, external_reference text, created_at timestamptz default now());
create table ratings (id uuid primary key default gen_random_uuid(), exchange_id uuid references exchange_proposals(id), from_user_id uuid references auth.users(id), to_user_id uuid references auth.users(id), rating int check(rating between 1 and 5), comment text, created_at timestamptz default now());
create table reports (id uuid primary key default gen_random_uuid(), reporter_id uuid references auth.users(id), reported_user_id uuid references auth.users(id), exchange_id uuid references exchange_proposals(id), reason text, status text default 'open', created_at timestamptz default now());
create table partners (id uuid primary key default gen_random_uuid(), name text not null, type text not null, logo_url text, is_active boolean default true, description text, created_at timestamptz default now());
create index idx_user_stickers_user on user_stickers(user_id); create index idx_user_stickers_sticker on user_stickers(sticker_id); create index idx_user_stickers_status on user_stickers(status); create index idx_profiles_city on profiles(city); create index idx_exchange_status on exchange_proposals(status); create index idx_shipments_tracking on shipments(tracking_number);
alter table profiles enable row level security; alter table user_stickers enable row level security; alter table exchange_proposals enable row level security;
create policy "profiles self" on profiles for all using (auth.uid() = id) with check (auth.uid() = id);
create policy "stickers self" on user_stickers for all using (auth.uid() = user_id) with check (auth.uid() = user_id);
create policy "exchange participants" on exchange_proposals for select using (auth.uid() = proposer_id or auth.uid() = receiver_id);
